const liveHeader = live.rest.match(LANES);
	if (!liveHeader) fail(live.n, `${pr.title}: Verify, live lacks the ten-lane header`);
	else if (
		/[<>]/.test(liveHeader[1]) ||
		liveHeader[1] !== liveHeader[1].trim() ||
		/^(?:auto|default|parent|inherit[-_]parent)$/i.test(liveHeader[1])
	)
		fail(live.n, `${pr.title}: Verify, live must name a concrete resolved model`);
	else if (LIVE_MODEL && liveHeader[1] !== LIVE_MODEL)
		fail(live.n, `${pr.title}: Verify, live names ${liveHeader[1]}, expected ${LIVE_MODEL}`);

# Transcripts dir: this workspace only, named by PSTACK_TRANSCRIPTS_DIR. When it
# is unset or missing, the last-chat column stays empty and no worktree is called
# safe on transcript evidence (see the bucket rule below).
transcripts="${PSTACK_TRANSCRIPTS_DIR:-}"
now=$(date +%s)

# stat and date differ between GNU and BSD; try GNU first, then BSD.
mtime_of() {
	stat -c '%Y' "$1" 2>/dev/null || stat -f '%m' "$1" 2>/dev/null
}
format_mtime() {
	date -d "@$1" '+%Y-%m-%d' 2>/dev/null || date -r "$1" '+%Y-%m-%d' 2>/dev/null
}
